"use client";

import type { Room } from "@/lib/palace-data";
import type { Word } from "@/components/PalaceWalkthrough";

// Stitches each room's existing connecting story (already generated by /api/palace/generate,
// see palace_room_stories) into one continuous read-through, in room order — a "walk" from the
// first room with a story to the last. No extra Gemini call: this is free, purely a different
// way of reading content that already exists.
export default function PalaceJourney({
  rooms,
  words,
  roomStories,
  onBack,
}: {
  rooms: Room[];
  words: Word[];
  roomStories: Record<string, string>;
  onBack: () => void;
}) {
  const steps = rooms.filter((room) => roomStories[room.id]);

  // A simple visual word chain — one stop per room that has at least one word placed in it,
  // connected by "→", no illustration. This is deliberately much lighter than a full narrative:
  // just enough to see the whole route and which words live where at a glance.
  const chainSteps = rooms
    .map((room) => ({ room, roomWords: words.filter((w) => w.palaceRoom === room.id) }))
    .filter((step) => step.roomWords.length > 0);

  return (
    <div className="flex flex-col gap-4">
      <button
        type="button"
        onClick={onBack}
        className="inline-flex items-center gap-1 self-start rounded-full border-2 border-black bg-white px-3 py-1.5 text-xs font-semibold text-black shadow-[2px_2px_0_0_#000] transition-all hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none active:translate-x-[2px] active:translate-y-[2px] active:shadow-none"
      >
        🗺️ Về sơ đồ nhà
      </button>

      {chainSteps.length > 0 && (
        <div className="rounded-2xl border-2 border-black bg-white p-4 shadow-[3px_3px_0_0_#000]">
          <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-neutral-500">
            🧭 Sơ đồ hành trình
          </p>
          <div className="flex flex-wrap items-center gap-x-2 gap-y-3">
            {chainSteps.map((step, index) => (
              <div key={step.room.id} className="flex items-center gap-2">
                <div className="relative flex max-w-[11rem] flex-col items-center gap-1 rounded-xl border-2 border-black bg-violet-50 px-3 py-2 text-center">
                  <span className="absolute -left-2 -top-2 flex h-5 w-5 items-center justify-center rounded-full border-2 border-black bg-amber-300 text-[10px] font-bold text-black">
                    {index + 1}
                  </span>
                  <span className="text-lg" aria-hidden>
                    {step.room.icon}
                  </span>
                  <span className="text-xs font-semibold text-black">{step.room.name}</span>
                  <span className="flex flex-wrap items-baseline justify-center gap-x-1 leading-snug">
                    {step.roomWords.map((w, i) => (
                      <span key={w.id} className="whitespace-nowrap">
                        <span className="text-sm font-bold text-black">{w.word}</span>
                        {w.meaning && (
                          <span className="text-[11px] text-neutral-500"> ({w.meaning})</span>
                        )}
                        {i < step.roomWords.length - 1 && (
                          <span className="text-neutral-400">,</span>
                        )}
                      </span>
                    ))}
                  </span>
                </div>
                {index < chainSteps.length - 1 && (
                  <span aria-hidden className="text-neutral-300">
                    →
                  </span>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {steps.length === 0 && chainSteps.length === 0 ? (
        <div className="rounded-2xl border-2 border-dashed border-black bg-white p-8 text-center">
          <span className="mx-auto mb-3 flex h-14 w-14 items-center justify-center rounded-2xl border-2 border-black bg-violet-100 text-2xl">
            📖
          </span>
          <p className="mb-1 font-semibold text-black">Chưa có hành trình nào</p>
          <p className="text-sm text-neutral-500">
            Tạo Cung điện trí nhớ cho vài phòng trước để có hành trình ở đây nhé.
          </p>
        </div>
      ) : steps.length === 0 ? null : (
        <div className="flex flex-col">
          <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-neutral-500">
            📖 Câu chuyện từng phòng
          </p>
          {steps.map((room, index) => (
            <div key={room.id} className="flex flex-col">
              <div className="rounded-2xl border-2 border-black bg-white p-4 shadow-[3px_3px_0_0_#000]">
                <div className="mb-2 flex items-center gap-2">
                  <span className="flex h-9 w-9 items-center justify-center rounded-xl border-2 border-black bg-violet-100 text-lg">
                    {room.icon}
                  </span>
                  <p className="font-semibold text-black">{room.name}</p>
                </div>
                <p className="text-sm text-neutral-700">{roomStories[room.id]}</p>
              </div>
              {index < steps.length - 1 && (
                <div aria-hidden className="py-1 text-center text-neutral-300">
                  ↓
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
